insert into public.parallel_stories (id, title_zh, title_id, hsk_level, content_pairs, audio_url) values ('00000000-0000-4000-8000-000000000201', '我的一天', 'Hariku', 1, '[{"zh":"我叫小明。","pinyin":"Wǒ jiào Xiǎo Míng.","id":"Nama saya Xiao Ming.","tokens":[{"w":"我","py":"wǒ","id":"saya"},{"w":"叫","py":"jiào","id":"bernama; dipanggil"},{"w":"小明","py":"Xiǎo Míng","id":"Xiao Ming (nama orang)"},{"w":"。"}]},{"zh":"我今天早上七点起床。","pinyin":"Wǒ jīntiān zǎoshang qī diǎn qǐchuáng.","id":"Hari ini saya bangun jam tujuh pagi.","tokens":[{"w":"我","py":"wǒ","id":"saya"},{"w":"今天","py":"jīntiān","id":"hari ini"},{"w":"早上","py":"zǎoshang","id":"pagi"},{"w":"七","py":"qī","id":"tujuh"},{"w":"点","py":"diǎn","id":"jam; pukul"},{"w":"起床","py":"qǐchuáng","id":"bangun tidur"},{"w":"。"}]},{"zh":"我喝一杯茶，吃一个包子。","pinyin":"Wǒ hē yì bēi chá, chī yí ge bāozi.","id":"Saya minum secangkir teh dan makan satu bakpao.","tokens":[{"w":"我","py":"wǒ","id":"saya"},{"w":"喝","py":"hē","id":"minum"},{"w":"一","py":"yì","id":"satu"},{"w":"杯","py":"bēi","id":"cangkir; gelas (kata bantu bilangan)"},{"w":"茶","py":"chá","id":"teh"},{"w":"，"},{"w":"吃","py":"chī","id":"makan"},{"w":"一","py":"yí","id":"satu"},{"w":"个","py":"ge","id":"kata bantu bilangan umum"},{"w":"包子","py":"bāozi","id":"bakpao"},{"w":"。"}]},{"zh":"然后我坐公共汽车去学校。","pinyin":"Ránhòu wǒ zuò gōnggòng qìchē qù xuéxiào.","id":"Lalu saya naik bus ke sekolah.","tokens":[{"w":"然后","py":"ránhòu","id":"lalu; kemudian"},{"w":"我","py":"wǒ","id":"saya"},{"w":"坐","py":"zuò","id":"naik (kendaraan); duduk"},{"w":"公共汽车","py":"gōnggòng qìchē","id":"bus"},{"w":"去","py":"qù","id":"pergi"},{"w":"学校","py":"xuéxiào","id":"sekolah"},{"w":"。"}]},{"zh":"我很喜欢学习中文！","pinyin":"Wǒ hěn xǐhuan xuéxí Zhōngwén!","id":"Saya sangat suka belajar bahasa Mandarin!","tokens":[{"w":"我","py":"wǒ","id":"saya"},{"w":"很","py":"hěn","id":"sangat"},{"w":"喜欢","py":"xǐhuan","id":"suka"},{"w":"学习","py":"xuéxí","id":"belajar"},{"w":"中文","py":"Zhōngwén","id":"bahasa Mandarin"},{"w":"！"}]}]'::jsonb, null)
  on conflict (id) do update set title_zh = excluded.title_zh, title_id = excluded.title_id, hsk_level = excluded.hsk_level, content_pairs = excluded.content_pairs, audio_url = excluded.audio_url;
insert into public.parallel_stories (id, title_zh, title_id, hsk_level, content_pairs, audio_url) values ('00000000-0000-4000-8000-000000000202', '在饭馆', 'Di Restoran', 2, '[{"zh":"今天是我朋友的生日。","pinyin":"Jīntiān shì wǒ péngyou de shēngrì.","id":"Hari ini ulang tahun teman saya.","tokens":[{"w":"今天","py":"jīntiān","id":"hari ini"},{"w":"是","py":"shì","id":"adalah"},{"w":"我","py":"wǒ","id":"saya"},{"w":"朋友","py":"péngyou","id":"teman"},{"w":"的","py":"de","id":"partikel kepemilikan"},{"w":"生日","py":"shēngrì","id":"ulang tahun"},{"w":"。"}]},{"zh":"我们去了一家新开的饭馆。","pinyin":"Wǒmen qù le yì jiā xīn kāi de fànguǎn.","id":"Kami pergi ke sebuah restoran yang baru buka.","tokens":[{"w":"我们","py":"wǒmen","id":"kami; kita"},{"w":"去","py":"qù","id":"pergi"},{"w":"了","py":"le","id":"partikel aksi selesai"},{"w":"一","py":"yì","id":"satu"},{"w":"家","py":"jiā","id":"kata bantu bilangan untuk toko/restoran"},{"w":"新","py":"xīn","id":"baru"},{"w":"开","py":"kāi","id":"buka"},{"w":"的","py":"de","id":"partikel atributif"},{"w":"饭馆","py":"fànguǎn","id":"restoran"},{"w":"。"}]},{"zh":"服务员问我们想吃什么。","pinyin":"Fúwùyuán wèn wǒmen xiǎng chī shénme.","id":"Pelayan bertanya kami ingin makan apa.","tokens":[{"w":"服务员","py":"fúwùyuán","id":"pelayan"},{"w":"问","py":"wèn","id":"bertanya"},{"w":"我们","py":"wǒmen","id":"kami"},{"w":"想","py":"xiǎng","id":"ingin"},{"w":"吃","py":"chī","id":"makan"},{"w":"什么","py":"shénme","id":"apa"},{"w":"。"}]},{"zh":"我们点了鱼、米饭和一些水果。","pinyin":"Wǒmen diǎn le yú, mǐfàn hé yìxiē shuǐguǒ.","id":"Kami memesan ikan, nasi, dan beberapa buah.","tokens":[{"w":"我们","py":"wǒmen","id":"kami"},{"w":"点","py":"diǎn","id":"memesan (makanan)"},{"w":"了","py":"le","id":"partikel aksi selesai"},{"w":"鱼","py":"yú","id":"ikan"},{"w":"、"},{"w":"米饭","py":"mǐfàn","id":"nasi"},{"w":"和","py":"hé","id":"dan"},{"w":"一些","py":"yìxiē","id":"beberapa"},{"w":"水果","py":"shuǐguǒ","id":"buah-buahan"},{"w":"。"}]},{"zh":"菜非常好吃，大家都很高兴。","pinyin":"Cài fēicháng hǎochī, dàjiā dōu hěn gāoxìng.","id":"Masakannya sangat enak, semua orang senang.","tokens":[{"w":"菜","py":"cài","id":"masakan; sayur"},{"w":"非常","py":"fēicháng","id":"sangat; luar biasa"},{"w":"好吃","py":"hǎochī","id":"enak"},{"w":"，"},{"w":"大家","py":"dàjiā","id":"semua orang"},{"w":"都","py":"dōu","id":"semua; sama-sama"},{"w":"很","py":"hěn","id":"sangat"},{"w":"高兴","py":"gāoxìng","id":"senang"},{"w":"。"}]}]'::jsonb, null)
  on conflict (id) do update set title_zh = excluded.title_zh, title_id = excluded.title_id, hsk_level = excluded.hsk_level, content_pairs = excluded.content_pairs, audio_url = excluded.audio_url;
insert into public.parallel_stories (id, title_zh, title_id, hsk_level, content_pairs, audio_url) values ('00000000-0000-4000-8000-000000000203', '去北京旅游', 'Berwisata ke Beijing', 3, '[{"zh":"去年夏天，我第一次去北京旅游。","pinyin":"Qùnián xiàtiān, wǒ dì-yī cì qù Běijīng lǚyóu.","id":"Musim panas tahun lalu, saya pertama kali berwisata ke Beijing.","tokens":[{"w":"去年","py":"qùnián","id":"tahun lalu"},{"w":"夏天","py":"xiàtiān","id":"musim panas"},{"w":"，"},{"w":"我","py":"wǒ","id":"saya"},{"w":"第一次","py":"dì-yī cì","id":"pertama kali"},{"w":"去","py":"qù","id":"pergi"},{"w":"北京","py":"Běijīng","id":"Beijing"},{"w":"旅游","py":"lǚyóu","id":"berwisata"},{"w":"。"}]},{"zh":"北京的天气比我想的热多了。","pinyin":"Běijīng de tiānqì bǐ wǒ xiǎng de rè duō le.","id":"Cuaca Beijing jauh lebih panas daripada yang saya kira.","tokens":[{"w":"北京","py":"Běijīng","id":"Beijing"},{"w":"的","py":"de","id":"partikel kepemilikan"},{"w":"天气","py":"tiānqì","id":"cuaca"},{"w":"比","py":"bǐ","id":"dibandingkan"},{"w":"我","py":"wǒ","id":"saya"},{"w":"想","py":"xiǎng","id":"mengira; berpikir"},{"w":"的","py":"de","id":"partikel"},{"w":"热","py":"rè","id":"panas"},{"w":"多了","py":"duō le","id":"jauh lebih"},{"w":"。"}]},{"zh":"我参观了长城，还爬到了最高的地方。","pinyin":"Wǒ cānguān le Chángchéng, hái pá dào le zuì gāo de dìfang.","id":"Saya mengunjungi Tembok Besar, dan bahkan mendaki sampai ke tempat tertinggi.","tokens":[{"w":"我","py":"wǒ","id":"saya"},{"w":"参观","py":"cānguān","id":"mengunjungi"},{"w":"了","py":"le","id":"partikel aksi selesai"},{"w":"长城","py":"Chángchéng","id":"Tembok Besar"},{"w":"，"},{"w":"还","py":"hái","id":"juga; bahkan"},{"w":"爬","py":"pá","id":"mendaki; memanjat"},{"w":"到","py":"dào","id":"sampai ke"},{"w":"了","py":"le","id":"partikel aksi selesai"},{"w":"最","py":"zuì","id":"paling"},{"w":"高","py":"gāo","id":"tinggi"},{"w":"的","py":"de","id":"partikel atributif"},{"w":"地方","py":"dìfang","id":"tempat"},{"w":"。"}]},{"zh":"虽然很累，但是风景特别漂亮。","pinyin":"Suīrán hěn lèi, dànshì fēngjǐng tèbié piàoliang.","id":"Meskipun sangat lelah, pemandangannya sangat indah.","tokens":[{"w":"虽然","py":"suīrán","id":"meskipun"},{"w":"很","py":"hěn","id":"sangat"},{"w":"累","py":"lèi","id":"lelah"},{"w":"，"},{"w":"但是","py":"dànshì","id":"tetapi"},{"w":"风景","py":"fēngjǐng","id":"pemandangan"},{"w":"特别","py":"tèbié","id":"sangat; khususnya"},{"w":"漂亮","py":"piàoliang","id":"indah; cantik"},{"w":"。"}]},{"zh":"我希望明年能再去一次。","pinyin":"Wǒ xīwàng míngnián néng zài qù yí cì.","id":"Saya berharap tahun depan bisa pergi sekali lagi.","tokens":[{"w":"我","py":"wǒ","id":"saya"},{"w":"希望","py":"xīwàng","id":"berharap"},{"w":"明年","py":"míngnián","id":"tahun depan"},{"w":"能","py":"néng","id":"bisa"},{"w":"再","py":"zài","id":"lagi"},{"w":"去","py":"qù","id":"pergi"},{"w":"一次","py":"yí cì","id":"sekali"},{"w":"。"}]}]'::jsonb, null)
