insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000310', 1, 'listening', '[{"kind":"mcq","id":"1l1","audio_text":"你好！我叫王芳。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Siapa nama orang itu?","options":["李明","王芳","张伟","小红"],"answer":1,"explanation":"“我叫王芳” berarti “Nama saya Wang Fang”. 叫 (jiào) dipakai untuk menyebut nama."},{"kind":"mcq","id":"1l2","audio_text":"我今天喝茶，不喝咖啡。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Apa yang dia minum hari ini?","options":["Kopi","Teh","Air","Susu"],"answer":1,"explanation":"喝茶 = minum teh; 不喝咖啡 = tidak minum kopi."},{"kind":"mcq","id":"1l3","audio_text":"现在是下午三点。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Jam berapa sekarang?","options":["03.00","13.00","15.00","15.30"],"answer":2,"explanation":"下午 = siang/sore, 三点 = jam tiga → pukul 15.00."},{"kind":"mcq","id":"1l4","audio_text":"我的妈妈是医生。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Apa pekerjaan ibunya?","options":["Guru","Dokter","Pelajar","Koki"],"answer":1,"explanation":"医生 (yīshēng) = dokter. 妈妈 = ibu."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000311', 1, 'reading', '[{"kind":"mcq","id":"1r1","passage_zh":"猫","prompt":"Apa arti karakter ini?","options":["Anjing","Kucing","Ikan","Burung"],"answer":1,"explanation":"猫 (māo) = kucing. Anjing = 狗, ikan = 鱼, burung = 鸟."},{"kind":"mcq","id":"1r2","passage_zh":"我在学校学习汉语。","prompt":"Di mana dia belajar?","options":["Di rumah","Di sekolah","Di restoran","Di rumah sakit"],"answer":1,"explanation":"在 + tempat menunjukkan lokasi. 学校 = sekolah."},{"kind":"mcq","id":"1r3","passage_zh":"A：你几岁了？ B：____","prompt":"Pilih jawaban yang tepat untuk B.","options":["我八岁了。","我是中国人。","我喜欢猫。","我叫小明。"],"answer":0,"explanation":"几岁 menanyakan umur (untuk anak-anak). Jawabannya: angka + 岁."},{"kind":"mcq","id":"1r4","passage_zh":"明天星期六，我不去学校。","prompt":"Mengapa dia tidak ke sekolah besok?","options":["Dia sakit","Besok hari Sabtu","Sekolah tutup karena hujan","Dia pindah"],"answer":1,"explanation":"星期六 = hari Sabtu. Kalimat menyiratkan tidak ada sekolah di hari Sabtu."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000312', 1, 'writing', '[{"kind":"order","id":"1w1","prompt":"Susun menjadi kalimat: “Saya orang Indonesia.”","fragments":["人","我","印度尼西亚","是"],"answer":"我是印度尼西亚人","explanation":"Pola: Subjek + 是 + nama negara + 人."},{"kind":"order","id":"1w2","prompt":"Susun menjadi kalimat: “Kamu mau minum apa?”","fragments":["喝","你","什么","想"],"answer":"你想喝什么","explanation":"Kata tanya 什么 tetap di posisi objek — tidak dipindah ke depan kalimat."},{"kind":"order","id":"1w3","prompt":"Susun menjadi kalimat: “Dia tidak suka kucing.”","fragments":["不","他","猫","喜欢"],"answer":"他不喜欢猫","explanation":"不 diletakkan tepat sebelum kata kerja yang dinegasikan."},{"kind":"mcq","id":"1w4","passage_zh":"我___中国人。","prompt":"Pilih karakter yang tepat.","options":["是","在","有","叫"],"answer":0,"explanation":"是 = adalah. 在 = berada di, 有 = punya, 叫 = bernama."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000320', 2, 'listening', '[{"kind":"mcq","id":"2l1","audio_text":"男：你怎么去机场？女：我打算坐出租车去。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Wanita itu naik apa ke bandara?","options":["Bus","Kereta","Taksi","Pesawat"],"answer":2,"explanation":"坐出租车 = naik taksi. 打算 = berencana."},{"kind":"mcq","id":"2l2","audio_text":"我比我姐姐高一点儿。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Siapa yang lebih tinggi?","options":["Kakak perempuannya","Pembicara","Sama tinggi","Tidak disebutkan"],"answer":1,"explanation":"Pola A 比 B + adj: A lebih ... daripada B. Pembicara (我) sedikit lebih tinggi."},{"kind":"mcq","id":"2l3","audio_text":"外面正在下雨，别忘了带伞。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Bagaimana cuaca di luar?","options":["Cerah","Bersalju","Hujan","Berangin"],"answer":2,"explanation":"正在下雨 = sedang hujan. 带伞 = bawa payung."},{"kind":"mcq","id":"2l4","audio_text":"这件衣服三百块，太贵了。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Menurut pembicara, baju itu…","options":["Terlalu mahal","Murah","Terlalu kecil","Bagus sekali"],"answer":0,"explanation":"太…了 = terlalu … ; 贵 = mahal."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000321', 2, 'reading', '[{"kind":"mcq","id":"2r1","passage_zh":"我已经吃过饭了，你们吃吧。","prompt":"Apa maksud pembicara?","options":["Dia belum makan","Dia sudah makan","Dia ingin makan bersama","Dia lapar sekali"],"answer":1,"explanation":"已经…了 = sudah. 吃过饭 = sudah makan."},{"kind":"mcq","id":"2r2","passage_zh":"因为生病了，所以小王今天没来上班。","prompt":"Mengapa Xiao Wang tidak masuk kerja?","options":["Bangun kesiangan","Sakit","Liburan","Macet"],"answer":1,"explanation":"因为…所以… = karena… maka… ; 生病 = sakit."},{"kind":"mcq","id":"2r3","passage_zh":"A：你的手机号码是多少？ B：____","prompt":"Pilih jawaban yang tepat untuk B.","options":["13812345678。","我的手机很新。","我在打电话。","我没有时间。"],"answer":0,"explanation":"号码是多少 menanyakan nomor, jadi jawabannya deretan angka."},{"kind":"mcq","id":"2r4","passage_zh":"从我家到公司要走二十分钟。","prompt":"Berapa lama berjalan dari rumah ke kantor?","options":["2 menit","12 menit","20 menit","2 jam"],"answer":2,"explanation":"从…到… = dari… ke… ; 二十分钟 = 20 menit."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000322', 2, 'writing', '[{"kind":"order","id":"2w1","prompt":"Susun menjadi kalimat: “Saya sedang membaca buku.”","fragments":["书","我","看","在"],"answer":"我在看书","explanation":"在 + kata kerja menunjukkan aksi yang sedang berlangsung."},{"kind":"order","id":"2w2","prompt":"Susun menjadi kalimat: “Dia lebih tinggi dari saya.”","fragments":["我","高","他","比"],"answer":"他比我高","explanation":"Pola perbandingan: A + 比 + B + kata sifat. Jangan tambahkan 很."},{"kind":"order","id":"2w3","prompt":"Susun menjadi kalimat: “Saya pernah ke Tiongkok.”","fragments":["过","中国","我","去"],"answer":"我去过中国","explanation":"Kata kerja + 过 menyatakan pengalaman di masa lalu."},{"kind":"mcq","id":"2w4","passage_zh":"你吃饭___吗？","prompt":"Isi titik-titik: “Kamu sudah makan?”","options":["了","的","过","着"],"answer":0,"explanation":"了 menandai aksi yang sudah selesai."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000330', 3, 'listening', '[{"kind":"mcq","id":"3l1","audio_text":"虽然今天很冷，但是他还是去公园跑步了。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Apa yang dia lakukan?","options":["Tetap di rumah","Lari di taman","Berenang","Menonton TV"],"answer":1,"explanation":"虽然…但是… = meskipun… tetapi… ; 还是 = tetap. 去公园跑步 = lari di taman."},{"kind":"mcq","id":"3l2","audio_text":"女：会议几点开始？男：本来是九点，现在改到十点半了。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Jam berapa rapat dimulai sekarang?","options":["09.00","09.30","10.00","10.30"],"answer":3,"explanation":"本来 = semula; 改到十点半 = diubah ke 10.30."},{"kind":"mcq","id":"3l3","audio_text":"我把钥匙忘在办公室了，进不了门。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Apa masalahnya?","options":["Kehilangan dompet","Kunci tertinggal di kantor","Pintu rusak","Terlambat kerja"],"answer":1,"explanation":"把钥匙忘在办公室 = kunci tertinggal di kantor; 进不了 = tidak bisa masuk."},{"kind":"mcq","id":"3l4","audio_text":"这个周末要是天气好的话，我们就去爬山吧。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Kapan mereka akan mendaki gunung?","options":["Pasti akhir pekan ini","Akhir pekan ini jika cuaca bagus","Besok","Bulan depan"],"answer":1,"explanation":"要是…的话，就… = jika… maka…. Rencananya bersyarat pada cuaca."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000331', 3, 'reading', '[{"kind":"mcq","id":"3r1","passage_zh":"小李最近工作特别忙，每天都要加班到很晚，连周末也不能休息。","prompt":"Bagaimana keadaan Xiao Li akhir-akhir ini?","options":["Sedang liburan","Sangat sibuk bekerja","Mencari pekerjaan","Sering bolos"],"answer":1,"explanation":"加班 = lembur; 连…也… = bahkan… pun…. Dia sangat sibuk."},{"kind":"mcq","id":"3r2","passage_zh":"这家超市的东西又便宜又新鲜，所以附近的人都喜欢来这儿买菜。","prompt":"Mengapa orang suka belanja di sini?","options":["Dekat stasiun","Murah dan segar","Buka 24 jam","Ada diskon"],"answer":1,"explanation":"又…又… = …dan juga…; 便宜 = murah, 新鲜 = segar."},{"kind":"mcq","id":"3r3","passage_zh":"请把窗户关上，外边风太大了。","prompt":"Apa yang diminta pembicara?","options":["Membuka jendela","Menutup jendela","Menyalakan AC","Keluar rumah"],"answer":1,"explanation":"把窗户关上 = tutup jendelanya. Alasannya angin di luar terlalu kencang."},{"kind":"mcq","id":"3r4","passage_zh":"他越说越激动，最后声音都变了。","prompt":"Pola 越…越… berarti…","options":["Semakin… semakin…","Baik… maupun…","Bukan… melainkan…","Jika… maka…"],"answer":0,"explanation":"越 A 越 B = semakin A semakin B: semakin bicara, semakin emosional."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000332', 3, 'writing', '[{"kind":"order","id":"3w1","prompt":"Susun menjadi kalimat: “Tolong letakkan buku di atas meja.”","fragments":["把","放在","请","书","桌子上"],"answer":"请把书放在桌子上","explanation":"Kalimat 把: (请) + 把 + objek + kata kerja + pelengkap tempat."},{"kind":"order","id":"3w2","prompt":"Susun menjadi kalimat: “Bahasa Mandarinnya semakin lama semakin bagus.”","fragments":["越来越","他的","好","汉语"],"answer":"他的汉语越来越好","explanation":"越来越 + kata sifat = semakin lama semakin …."},{"kind":"order","id":"3w3","prompt":"Susun menjadi kalimat: “Saya sudah belajar bahasa Mandarin selama dua tahun.”","fragments":["两年","汉语","我","了","学了"],"answer":"我学了两年汉语了","explanation":"Durasi diletakkan setelah V+了; 了 di akhir menandakan aksi masih berlanjut."},{"kind":"mcq","id":"3w4","passage_zh":"他跑___很快。","prompt":"Pilih partikel yang tepat.","options":["得","的","地","了"],"answer":0,"explanation":"得 menghubungkan kata kerja dengan pelengkap derajat: 跑得很快 = larinya cepat."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000340', 4, 'listening', '[{"kind":"mcq","id":"4l1","audio_text":"这次面试我准备得很充分，所以一点儿也不紧张。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Bagaimana perasaannya?","options":["Sangat gugup","Sama sekali tidak gugup","Kecewa","Marah"],"answer":1,"explanation":"准备得很充分 = persiapannya matang; 一点儿也不紧张 = sama sekali tidak gugup."},{"kind":"mcq","id":"4l2","audio_text":"男：咱们打车去吧？女：这个时间肯定堵车，还不如坐地铁呢。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Wanita itu menyarankan apa?","options":["Naik taksi","Naik subway","Jalan kaki","Naik bus"],"answer":1,"explanation":"还不如 = lebih baik…. 坐地铁 = naik subway karena pasti macet."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000341', 4, 'reading', '[{"kind":"mcq","id":"4r1","passage_zh":"随着科技的发展，越来越多的人习惯在网上购物，这不仅节约了时间，而且价格往往更便宜。","prompt":"Apa keuntungan belanja online menurut teks?","options":["Barang lebih bagus","Hemat waktu dan sering lebih murah","Pengiriman gratis","Bisa dicoba dulu"],"answer":1,"explanation":"不仅…而且… = tidak hanya… tetapi juga…: 节约了时间 dan 价格往往更便宜."},{"kind":"mcq","id":"4r2","passage_zh":"他之所以能成功，是因为他从来没有放弃过。","prompt":"Mengapa dia berhasil?","options":["Karena keberuntungan","Karena tidak pernah menyerah","Karena kaya","Karena dibantu teman"],"answer":1,"explanation":"之所以…是因为… = alasan… adalah karena…; 从来没有放弃过 = tidak pernah menyerah."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000342', 4, 'writing', '[{"kind":"order","id":"4w1","prompt":"Susun menjadi kalimat: “Masalah ini sudah diselesaikan olehnya.”","fragments":["被","这个问题","解决了","他"],"answer":"这个问题被他解决了","explanation":"Kalimat pasif: objek + 被 + pelaku + kata kerja + 了."},{"kind":"order","id":"4w2","prompt":"Susun menjadi kalimat: “Saya sangat tertarik pada budaya Tiongkok.”","fragments":["对","感兴趣","我","中国文化","很"],"answer":"我对中国文化很感兴趣","explanation":"Pola: S + 对 + sesuatu + (很) 感兴趣."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000350', 5, 'listening', '[{"kind":"mcq","id":"5l1","audio_text":"尽管这个方案还有一些不足，但总的来说是可行的。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Bagaimana penilaian terhadap rencana itu?","options":["Sempurna","Ada kekurangan tetapi secara umum layak","Sama sekali tidak layak","Belum dibaca"],"answer":1,"explanation":"尽管…但… = meskipun… tetapi…; 可行 = layak dijalankan."},{"kind":"mcq","id":"5l2","audio_text":"女：听说你辞职了？男：是啊，我打算自己创业，趁年轻多闯一闯。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Apa rencana pria itu?","options":["Melanjutkan kuliah","Memulai usaha sendiri","Pindah ke luar negeri","Pensiun"],"answer":1,"explanation":"创业 = merintis usaha; 趁年轻 = selagi muda."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000351', 5, 'reading', '[{"kind":"mcq","id":"5r1","passage_zh":"适当的压力能使人保持积极的状态，然而压力过大则会影响身心健康。","prompt":"Apa gagasan utama kalimat ini?","options":["Tekanan selalu buruk","Tekanan yang tepat bermanfaat, berlebihan merugikan","Hindari semua tekanan","Tekanan tidak berpengaruh"],"answer":1,"explanation":"适当 = secukupnya; 然而…则… menyajikan kontras: terlalu besar akan merugikan."},{"kind":"mcq","id":"5r2","passage_zh":"他做事向来一丝不苟，领导对他非常放心。","prompt":"Apa makna 一丝不苟?","options":["Ceroboh","Sangat teliti dan cermat","Lambat","Malas"],"answer":1,"explanation":"成语 一丝不苟 = tidak melewatkan sehelai benang pun → sangat teliti."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000352', 5, 'writing', '[{"kind":"order","id":"5w1","prompt":"Susun menjadi kalimat: “Asalkan kamu berusaha, pasti akan berhasil.”","fragments":["只要","你","努力","就","一定会成功"],"answer":"只要你努力就一定会成功","explanation":"只要…就… = asalkan… maka…."},{"kind":"mcq","id":"5w2","passage_zh":"这个问题我们必须认真___。","prompt":"Pilih kata yang tepat.","options":["对待","对付","对比","对话"],"answer":0,"explanation":"认真对待 = menangani dengan serius. 对付 bernuansa ‘menghadapi lawan’."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000360', 6, 'listening', '[{"kind":"mcq","id":"6l1","audio_text":"这部小说情节跌宕起伏，引人入胜，一经出版便成为畅销书。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Apa yang dikatakan tentang novel itu?","options":["Membosankan","Alurnya menarik dan menjadi best-seller","Belum terbit","Ditulis untuk anak"],"answer":1,"explanation":"跌宕起伏 = penuh liku; 引人入胜 = memikat; 畅销书 = buku laris."},{"kind":"mcq","id":"6l2","audio_text":"与其抱怨环境，不如改变自己。","prompt":"Dengarkan audio, lalu pilih jawaban yang benar. Apa makna kalimat ini?","options":["Lebih baik mengubah diri daripada mengeluhkan lingkungan","Lingkungan harus diubah","Mengeluh itu wajar","Diri sendiri tidak bisa diubah"],"answer":0,"explanation":"与其 A 不如 B = daripada A, lebih baik B."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000361', 6, 'reading', '[{"kind":"mcq","id":"6r1","passage_zh":"城市化进程的加快在带来经济繁荣的同时，也引发了交通拥堵、住房紧张等一系列问题。","prompt":"Menurut teks, urbanisasi…","options":["Hanya membawa keuntungan","Membawa kemakmuran tetapi juga masalah","Sudah berhenti","Tidak berdampak pada perumahan"],"answer":1,"explanation":"在…的同时，也… = sambil…, juga…. Ada sisi positif dan negatif."},{"kind":"mcq","id":"6r2","passage_zh":"他的建议可谓一针见血，大家听了都深受启发。","prompt":"Apa arti 一针见血?","options":["Menyakitkan","Tepat sasaran / langsung ke inti","Bertele-tele","Menakutkan"],"answer":1,"explanation":"成语 一针见血 = satu tusukan langsung berdarah → kritik yang tepat sasaran."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;
insert into public.hsk_exams (id, hsk_level, section_type, questions_json) values ('00000000-0000-4000-8000-000000000362', 6, 'writing', '[{"kind":"mcq","id":"6w1","passage_zh":"面对困难，我们要___，不能轻易放弃。","prompt":"Pilih 成语 yang tepat.","options":["坚持不懈","半途而废","无所事事","得过且过"],"answer":0,"explanation":"坚持不懈 = gigih tanpa henti. 半途而废 justru berarti menyerah di tengah jalan."},{"kind":"order","id":"6w2","prompt":"Susun menjadi kalimat: “Teknologi ini tidak hanya meningkatkan efisiensi tetapi juga menurunkan biaya.”","fragments":["不仅","而且","这项技术","提高了效率","降低了成本"],"answer":"这项技术不仅提高了效率而且降低了成本","explanation":"不仅…而且… menghubungkan dua predikat untuk subjek yang sama."}]'::jsonb)
  on conflict (id) do update set hsk_level = excluded.hsk_level, section_type = excluded.section_type, questions_json = excluded.questions_json;

commit;
